    27→public sealed class BlockCachePreWarmer(
    28→    IReadOnlyTxProcessingEnvFactory envFactory,
    29→    IWorldState worldStateToWarmup,
    30→    int concurrency,
    31→    ILogManager logManager,
    32→    PreBlockCaches? preBlockCaches = null
    33→) : IBlockCachePreWarmer
    34→{
    35→    private int _concurrencyLevel = (concurrency == 0 ? Math.Min(Environment.ProcessorCount - 1, 16) : concurrency);
    36→    private readonly ObjectPool<IReadOnlyTxProcessorSource> _envPool = new DefaultObjectPool<IReadOnlyTxProcessorSource>(new ReadOnlyTxProcessingEnvPooledObjectPolicy(envFactory, worldStateToWarmup), Environment.ProcessorCount * 2);
    37→    private readonly ILogger _logger = logManager.GetClassLogger<BlockCachePreWarmer>();
    38→    private BlockStateSource? _currentBlockState = null;
    39→
    40→    public BlockCachePreWarmer(
    41→        IReadOnlyTxProcessingEnvFactory envFactory,
    42→        IWorldState worldStateToWarmup,
    43→        IBlocksConfig blocksConfig,
    44→        ILogManager logManager,
    45→        PreBlockCaches? preBlockCaches = null
    46→    ) : this(
    47→        envFactory,
    48→        worldStateToWarmup,
    49→        blocksConfig.PreWarmStateConcurrency,
    50→        logManager,
    51→        preBlockCaches)
    52→    {
    53→    }
