    55→    public Task PreWarmCaches(Block suggestedBlock, BlockHeader? parent, IReleaseSpec spec, CancellationToken cancellationToken = default, params ReadOnlySpan<IHasAccessList> systemAccessLists)
    56→    {
    57→        if (preBlockCaches is not null)
    58→        {
    59→            _currentBlockState = new(this, suggestedBlock, parent, spec);
    60→            CacheType result = preBlockCaches.ClearCaches();
    61→            if (result != default)
    62→            {
    63→                if (_logger.IsWarn) _logger.Warn($"Caches {result} are not empty. Clearing them.");
    64→            }
    65→
    66→            if (parent is not null && _concurrencyLevel > 1 && !cancellationToken.IsCancellationRequested)
    67→            {
    68→                ParallelOptions parallelOptions = new() { MaxDegreeOfParallelism = _concurrencyLevel, CancellationToken = cancellationToken };
    69→
    70→                // Run address warmer ahead of transactions warmer, but queue to ThreadPool so it doesn't block the txs
    71→                var addressWarmer = new AddressWarmer(parallelOptions, suggestedBlock, parent, spec, systemAccessLists, this);
    72→                ThreadPool.UnsafeQueueUserWorkItem(addressWarmer, preferLocal: false);
    73→                // Do not pass cancellation token to the task, we don't want exceptions to be thrown in main processing thread
    74→                return Task.Run(() => PreWarmCachesParallel(_currentBlockState, suggestedBlock, parent, spec, parallelOptions, addressWarmer, cancellationToken));
    75→            }
    76→        }
    77→
    78→        return Task.CompletedTask;
    79→    }
    80→
    81→    public CacheType ClearCaches()
    82→    {
    83→        if (_logger.IsDebug) _logger.Debug("Clearing caches");
    84→        CacheType cachesCleared = preBlockCaches?.ClearCaches() ?? default;
    85→        if (_logger.IsDebug) _logger.Debug($"Cleared caches: {cachesCleared}");
    86→
    87→        return cachesCleared;
    88→    }
    89→
    90→    private void PreWarmCachesParallel(BlockStateSource blockState, Block suggestedBlock, BlockHeader parent, IReleaseSpec spec, ParallelOptions parallelOptions, AddressWarmer addressWarmer, CancellationToken cancellationToken)
    91→    {
    92→        try
    93→        {
    94→            if (cancellationToken.IsCancellationRequested) return;
    95→
    96→            if (_logger.IsDebug) _logger.Debug($"Started pre-warming caches for block {suggestedBlock.Number}.");
    97→
    98→            WarmupTransactions(blockState, parallelOptions);
    99→            WarmupWithdrawals(parallelOptions, spec, suggestedBlock, parent);
   100→
   101→            if (_logger.IsDebug) _logger.Debug($"Finished pre-warming caches for block {suggestedBlock.Number}.");
   102→        }
   103→        catch (Exception ex)
   104→        {
   105→            if (_logger.IsDebug) _logger.Warn($"DEBUG/ERROR Error pre-warming {suggestedBlock.Number}. {ex}");
   106→        }
   107→        finally
   108→        {
   109→            // Don't compete task until address warmer is also done.
   110→            addressWarmer.Wait();
   111→        }
   112→    }
   113→
   114→    public void OnBeforeTxExecution(Transaction transaction)
   115→    {
   116→        _currentBlockState?.IncrementTransactionCounter();
   117→    }
   118→
   119→    private void WarmupWithdrawals(ParallelOptions parallelOptions, IReleaseSpec spec, Block block, BlockHeader? parent)
   120→    {
   121→        if (parallelOptions.CancellationToken.IsCancellationRequested) return;
   122→
   123→        try
   124→        {
   125→            if (spec.WithdrawalsEnabled && block.Withdrawals is not null)
   126→            {
