   128→                    static (i, state) =>
   129→                    {
   130→                        IReadOnlyTxProcessorSource env = state.envPool.Get();
   131→                        try
   132→                        {
   133→                            using IReadOnlyTxProcessingScope scope = env.Build(state.parent);
   134→                            scope.WorldState.WarmUp(state.block.Withdrawals[i].Address);
   135→                        }
   136→                        catch (MissingTrieNodeException)
   137→                        {
   138→                        }
   139→                        finally
   140→                        {
   141→                            state.envPool.Return(env);
   142→                        }
   143→
   144→                        return state;
   145→                    });
   146→            }
   147→        }
   148→        catch (OperationCanceledException)
